package cn.huankan.collector;
import java.util.*;import java.time.*;import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionTemplate;
@Service public class BlsFileCollector {
 private final JdbcTemplate db;private final EvidenceService evidence;private final OfficialResourceService resources;private final CollectorGuard guard;private final TransactionTemplate tx;
 public BlsFileCollector(JdbcTemplate d,EvidenceService e,OfficialResourceService r,CollectorGuard g,org.springframework.transaction.PlatformTransactionManager m){db=d;evidence=e;resources=r;guard=g;tx=new TransactionTemplate(m);}
 public Object sync(int first,int last){String base="https://download.bls.gov/pub/time.series/cu/";if(first<1900||last<first||last-first>9||last>LocalDate.now().getYear())throw new IllegalArgumentException("同步年份无效");if(!Boolean.TRUE.equals(db.queryForObject("SELECT status='APPROVED' AND access_allowed AND storage_allowed AND display_allowed AND (valid_until IS NULL OR valid_until>now()) FROM source_license WHERE source_id='BLS'",Boolean.class)))throw new IllegalStateException("BLS许可未通过");var inputs=new ArrayList<Map<String,Object>>();for(String file:List.of("cu.series","cu.data.1.AllItems","cu.footnote")){var rows=db.queryForList("SELECT r.* FROM official_resource_response r JOIN official_resource_policy p ON p.url=r.url WHERE r.url=? AND r.http_status=200 AND r.error IS NULL AND p.storage_allowed AND p.display_allowed ORDER BY received_at DESC LIMIT 1",base+file);if(rows.isEmpty())return Map.of("inserted",0,"state","官方文件被拒绝或元数据不足，批量入库关闭");var row=rows.getFirst();if(!EvidenceService.hash((byte[])row.get("raw_content")).equals(row.get("sha256")))throw new IllegalStateException("官方文件哈希错误");inputs.add(row);}
  var points=BlsFileAdapter.parse((byte[])inputs.get(0).get("raw_content"),(byte[])inputs.get(1).get("raw_content"),(byte[])inputs.get(2).get("raw_content"),first,last);
  if(points.isEmpty())return Map.of("fetched",0,"inserted",0,"duplicates",0,"state","所选年份暂无实际观测");
  try(var lease=guard.acquire("BLS")){if(lease==null)throw new IllegalStateException("BLS已有采集任务");UUID job=UUID.randomUUID();return tx.execute(s->{db.update("INSERT INTO ingestion_job(id,source_id,status) VALUES(?,'BLS','RUNNING')",job);UUID response=UUID.randomUUID();String url=base+"cu.data.1.AllItems";byte[] raw=(byte[])inputs.get(1).get("raw_content");db.update("INSERT INTO official_response(id,source_id,job_id,url,response_status,raw_content,sha256) VALUES(?,'BLS',?,?,200,?,?)",response,job,url,raw,EvidenceService.hash(raw));db.update("INSERT INTO macro_series(id,source_id,flow,series_key,title,units,frequency,metadata,response_id) VALUES('CUUR0000SA0','BLS','BLS_OFFICIAL_FILE','CUUR0000SA0','美国CPI全项目（未季调）','指数，1982-84=100','M',?::jsonb,?) ON CONFLICT(id) DO UPDATE SET response_id=excluded.response_id,updated_at=now()",resources.encode(points.getFirst().metadata()),response);int inserted=0;for(var p:points){String doc="CUUR0000SA0:"+p.date();int n=evidence.persist("BLS",job,raw,List.of(new SourceAdapter.Item(doc,"美国CPI全项目（未季调） · "+p.date()+" · "+p.rawValue()+" · "+p.footnotes(),url,null,"美国官方宏观数据")),Instant.now(),true);inserted+=n;UUID id=db.queryForObject("SELECT id FROM raw_evidence WHERE source_id='BLS' AND source_document_id=? ORDER BY revision DESC LIMIT 1",UUID.class,doc);db.update("INSERT INTO macro_observation(evidence_id,series_id,observation_date,value,observation_status,version) SELECT ?,'CUUR0000SA0',?,?, 'UNKNOWN',revision FROM raw_evidence WHERE id=? ON CONFLICT DO NOTHING",id,java.sql.Date.valueOf(p.date()),p.value(),id);db.update("INSERT INTO bls_file_observation(evidence_id,data_response_id,series_response_id,footnote_response_id,raw_line,footnotes,metadata) VALUES(?,?,?,?,?,?::jsonb,?::jsonb) ON CONFLICT DO NOTHING",id,inputs.get(1).get("id"),inputs.get(0).get("id"),inputs.get(2).get("id"),p.line(),resources.encode(p.footnotes()),resources.encode(p.metadata()));db.update("INSERT INTO response_evidence VALUES(?,?) ON CONFLICT DO NOTHING",response,id);if(n>0){UUID fact=UUID.randomUUID();int version=db.queryForObject("SELECT revision FROM raw_evidence WHERE id=?",Integer.class,id);var fields=new LinkedHashMap<String,Object>();fields.put("indicator_id","CUUR0000SA0");fields.put("observation_period",p.date().toString());fields.put("actual_value",p.value());fields.put("unit","指数，1982-84=100");fields.put("frequency","M");fields.put("seasonal_adjustment","未季调");fields.put("footnotes",p.footnotes());fields.put("source_published_at",null);fields.put("market_expectation",null);fields.put("interpretation","月份不是首次发布时间；文件Last-Modified不是公告时间");db.update("INSERT INTO fact_candidate(id,fact_key,version,fact_type,observation_id,fields,extraction_method,verification_status) VALUES(?,?,?,'MACRO_OBSERVATION',?,?::jsonb,'BLS官方TSV字段核对-1.0','FIELD_MATCHED')",fact,"macro:"+doc,version,id,resources.encode(fields));db.update("INSERT INTO fact_evidence VALUES(?,?,?,?)",fact,id,p.line(),"官方TSV:series_id=CUUR0000SA0,date="+p.date());db.update("INSERT INTO fact_revision SELECT ?,id,'官方文件同期数值或脚注变化；源端修订公布时间未知' FROM fact_candidate WHERE fact_key=? AND version<? ORDER BY version DESC LIMIT 1",fact,"macro:"+doc,version);}}db.update("UPDATE ingestion_job SET status='SUCCESS',finished_at=now(),http_status=200,new_count=?,fetched_count=?,duplicate_count=? WHERE id=?",inserted,points.size(),points.size()-inserted,job);return Map.of("job_id",job,"fetched",points.size(),"inserted",inserted,"duplicates",points.size()-inserted);});}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("BLS批量同步失败，事务未提交",e);}
 }
}
